// apiVersion: auth0.planton.dev/v1alpha1
// kind: Auth0EmailTemplate
// metadata:
//
//	name: verify-email
//	org: my-organization
//
// spec:
//
//	template: verify_email
//	from: Acme <no-reply@acme.com>
//	subject: Verify your email for Acme
